function Brand({ onHome }: { onHome: () => void }) {
  return (
    <a
      className="brand"
      href="#accueil"
      aria-label="BDEAC, accueil"
      onClick={onHome}
    >
      <span className="brand-mark" aria-hidden="true">
        <span>BDEAC</span>
        <span className="brand-center">✦</span>
        <span>1960</span>
      </span>
      <span className="brand-name">
        <strong>Banque de Développement des États</strong>
        <strong>de l'Afrique Centrale</strong>
        <small>Investir pour l'avenir · servir la région</small>
      </span>
    </a>
  );
}

function HomeIcon() {
  return (
    <svg
      aria-hidden="true"
      className="home-icon"
      viewBox="0 0 40 40"
      fill="none"
    >
      <path
        d="M4 18.5 20 5l16 13.5M9 16v18h22V16M16 34V23h8v11"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="3.5"
      />
    </svg>
  );
}

export default function Home() {
  const [activeSlide, setActiveSlide] = useState(0);
  const [activePage, setActivePage] = useState<number | null>(null);
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  const [contactReady, setContactReady] = useState(false);
  const [formValues, setFormValues] = useState<Record<string, string>>({});
  const [scrollToSubscription, setScrollToSubscription] = useState(false);

  useEffect(() => {
    if (activePage === null && scrollToSubscription) {
      document
        .getElementById("souscription")
        ?.scrollIntoView({ behavior: "smooth" });
      setScrollToSubscription(false);
    }
  }, [activePage, scrollToSubscription]);

  function handleContactSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const subject = `Message du site BDEAC — ${formData.get("contact-name")} ${formData.get("contact-first-name")}`;
    const body = [
      `Nom : ${formData.get("contact-name")}`,
      `Prénom : ${formData.get("contact-first-name")}`,
      `E-mail : ${formData.get("contact-email")}`,
      "",
      "Message :",
      formData.get("contact-message"),
    ].join("\n");
    window.location.href = `mailto:${CONTACT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    setContactReady(true);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (step < 3) {
      setStep(step + 1);
      return;
    }
    setSubmitted(true);
  }

  function updateField(event: React.ChangeEvent<HTMLInputElement>) {
    setFormValues({ ...formValues, [event.target.name]: event.target.value });
  }

  return (
    <main className="site-shell" id="accueil">
      <header className="topbar">
        <Brand onHome={() => setActivePage(null)} />
        <span className="tagline">Investir pour l'avenir…</span>
        <nav className="top-links" aria-label="Navigation principale">
          <a href="#contact">Contacts</a>
          <a href="#agences">Nos agences</a>
          <a className="login-button" href="#connexion">
            Se connecter
          </a>
        </nav>
      </header>

      <div className="page-columns">
        <aside className="sidebar">
          <nav className="side-navigation" aria-label="Navigation du site">
            <button
              aria-current={activePage === null ? "page" : undefined}
              className={`home-link${activePage === null ? " active" : ""}`}
              onClick={() => setActivePage(null)}
              type="button"
            >
              <HomeIcon />
              <span>Accueil</span>
            </button>
            {navigation.map((item, index) => (
              <button
                aria-current={activePage === index ? "page" : undefined}
                className={`side-link${activePage === index ? " active" : ""}`}
                key={item}
                onClick={() => setActivePage(index)}
                type="button"
              >
                {item}
              </button>
            ))}
            <button
              className="subscribe-button"
              onClick={() => {
                setScrollToSubscription(true);
                setActivePage(null);
              }}
              type="button"
            >
              JE SOUSCRIS
            </button>
          </nav>

          <section className="contact-card" id="contact">
            <h2>Nous contacter</h2>
            <form className="contact-form" onSubmit={handleContactSubmit}>
              <label>
                <span>Nom</span>
                <input aria-label="Nom" name="contact-name" required />
              </label>
              <label>
                <span>Prénom</span>
                <input aria-label="Prénom" name="contact-first-name" required />
              </label>
              <label>
                <span>E-mail</span>
                <input
                  aria-label="E-mail"
                  name="contact-email"
                  required
                  type="email"
                />
              </label>
              <textarea
                aria-label="Votre message"
                name="contact-message"
                required
                rows={4}
              />
              <button type="submit">ENVOYER</button>
              {contactReady && (
                <p className="contact-feedback" role="status">
                  Votre application de messagerie va s’ouvrir avec votre
                  message prérempli. Il vous restera à l’envoyer.
                </p>
              )}
            </form>
            <p className="contact-email">
              Ou écrivez-nous directement :{" "}
              <a href={`mailto:${CONTACT_EMAIL}`}>{CONTACT_EMAIL}</a>
            </p>
          </section>
        </aside>

        <section className="main-content" id="contenu">
          {activePage === null ? (
            <>
          <div className="carousel">
            <img
              src={slides[activeSlide].image}
              alt={slides[activeSlide].alt}
            />
            <div className="carousel-dots" aria-label="Choisir une image">
              {slides.map((slide, index) => (
                <button
                  aria-label={`Afficher : ${slide.title}`}
                  aria-pressed={activeSlide === index}
                  className={activeSlide === index ? "active" : ""}
                  key={slide.title}
                  onClick={() => setActiveSlide(index)}
                  type="button"
                />
              ))}
            </div>
          </div>

          <div className="intro-copy">
            <p>
              La BDEAC est au service du développement économique et social des
              pays de la Communauté Économique et Monétaire de l'Afrique
              Centrale. Elle accompagne les projets porteurs de croissance et
              d'emplois dans toute la sous-région.
            </p>
            <p>
              À travers cette opération, chacun peut participer au financement
              d'initiatives durables et contribuer à bâtir une prospérité
              partagée.
            </p>
          </div>

          <section className="subscription" id="souscription">
            <div className="step-tabs" aria-label="Étapes de souscription">
              {[1, 2, 3].map((number) => (
                <button
                  aria-current={step === number ? "step" : undefined}
                  className={step === number ? "selected" : ""}
                  key={number}
                  onClick={() => setStep(number)}
                  type="button"
                >
                  Étape {number}
                </button>
              ))}
            </div>
            <form className="subscription-form" onSubmit={handleSubmit}>
              {submitted ? (
                <div className="success-message" role="status">
                  Merci ! Votre demande est prête. Elle pourra être transmise
                  lorsque le site sera relié à un service de traitement.
                </div>
              ) : (
                <>
                  {step === 1 && (
                    <div className="form-grid">
                      <label>
                        <span>Nom</span>
                        <input
                          autoComplete="family-name"
                          name="lastName"
                          onChange={updateField}
                          required
                          value={formValues.lastName ?? ""}
                        />
                      </label>
                      <label>
                        <span>Prénom</span>
                        <input
                          autoComplete="given-name"
                          name="firstName"
                          onChange={updateField}
                          required
                          value={formValues.firstName ?? ""}
                        />
                      </label>
                      <label>
                        <span>E-mail</span>
                        <input
                          autoComplete="email"
                          name="email"
                          onChange={updateField}
                          required
                          type="email"
                          value={formValues.email ?? ""}
                        />
                      </label>
                      <label>
                        <span>Tél</span>
                        <input
                          autoComplete="tel"
                          name="phone"
                          onChange={updateField}
                          required
                          type="tel"
                          value={formValues.phone ?? ""}
                        />
                      </label>
                      <label className="shares-field">
                        <span>Nombre de parts</span>
                        <input
                          min="1"
                          name="shares"
                          onChange={updateField}
                          required
                          type="number"
                          value={formValues.shares ?? ""}
                        />
                      </label>
                    </div>
                  )}
                  {step === 2 && (
                    <div className="form-grid">
                      <label>
                        <span>Adresse</span>
                        <input
                          autoComplete="street-address"
                          name="address"
                          onChange={updateField}
                          required
                          value={formValues.address ?? ""}
                        />
                      </label>
                      <label>
                        <span>Ville</span>
                        <input
                          autoComplete="address-level2"
                          name="city"
                          onChange={updateField}
                          required
                          value={formValues.city ?? ""}
                        />
                      </label>
                      <label>
                        <span>Pays</span>
                        <input
                          autoComplete="country-name"
                          name="country"
                          onChange={updateField}
                          required
                          value={formValues.country ?? ""}
                        />
                      </label>
                      <label>
                        <span>Nationalité</span>
                        <input
                          name="nationality"
                          onChange={updateField}
                          required
                          value={formValues.nationality ?? ""}
                        />
                      </label>
                    </div>
                  )}
                  {step === 3 && (
                    <div className="confirmation">
                      <p>Vérifiez vos informations avant de confirmer.</p>
                      <label className="consent">
                        <input required type="checkbox" />
                        <span>
                          J'accepte les conditions de souscription et confirme
                          l'exactitude des informations fournies.
                        </span>
                      </label>
                    </div>
                  )}
                  <button className="next-button" type="submit">
                    {step === 3 ? "Confirmer" : "Suivant"}
                  </button>
                </>
              )}
            </form>
          </section>
            </>
          ) : (
            <article
              aria-labelledby="section-title"
              className="section-page"
              key={activePage}
            >
              <figure className="section-hero">
                <img
                  alt={operationPages[activePage].imageAlt}
                  src={operationPages[activePage].image}
                />
                <figcaption>{operationPages[activePage].title}</figcaption>
              </figure>
              <div
                aria-label="Navigation entre les rubriques"
                className="carousel-dots section-dots"
              >
                {operationPages.map((page, index) => (
                  <button
                    aria-label={`Afficher : ${page.title}`}
                    aria-pressed={activePage === index}
                    className={activePage === index ? "active" : ""}
                    key={page.title}
                    onClick={() => setActivePage(index)}
                    type="button"
                  />
                ))}
              </div>
              <p className="section-eyebrow">
                {operationPages[activePage].eyebrow}
              </p>
              <h1 id="section-title">{operationPages[activePage].title}</h1>
              <p className="section-intro">{operationPages[activePage].intro}</p>
              <div className="section-cards">
                {operationPages[activePage].blocks.map((block, index) => (
                  <section className="section-card" key={block.title}>
                    <span className="section-card-number">
                      {String(index + 1).padStart(2, "0")}
                    </span>
                    <div>
                      <h2>{block.title}</h2>
                      <p>{block.text}</p>
                    </div>
                  </section>
                ))}
              </div>
              <button
                className="section-back"
                onClick={() => setActivePage(null)}
                type="button"
              >
                Retour à l'accueil
              </button>
            </article>
          )}
        </section>
      </div>

      <footer className="footer">
        <a href="#plan">Plan du site</a>
        <a href="#mentions">Mentions Légales</a>
      </footer>
    </main>
  );
}
